import Svg, { Circle, G, Path, Polyline, Rect } from "react-native-svg";

import { COLORS } from "@/constants/colors";
import type { IconProps } from "@/types";

/**
 * Hand-rolled icon set. The app needs a small, fixed set of glyphs, so local SVG
 * components are cheaper than an icon font and let the Google mark keep its
 * brand colours. Glyphs exported from Figma keep their own viewBox, so a single
 * `size` scales them to fit without distorting the artwork.
 */

export function ChevronLeftIcon({ size = 20, color = COLORS.foreground }: IconProps) {
  return (
    <Svg width={size} height={size} viewBox="0 0 24 24" fill="none">
      <Path
        d="M15 18L9 12L15 6"
        stroke={color}
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </Svg>
  );
}

